const output = $input.first().json.output;

let result;

try {
  result = typeof output === 'string' ? JSON.parse(output) : output;
} catch (error) {
  throw new Error(`AI Agent returned invalid JSON: ${error.message}`);
}

if (!result || !Array.isArray(result.changes)) {
  throw new Error('AI Agent output must contain a changes array');
}

for (const change of result.changes) {
  if (typeof change.content !== 'string') {
    throw new Error(`Missing content for ${change.file_path}`);
  }
}

return result.changes.map(change => ({
  json: {
    file_path: `/workspace/docs/${change.file_path}`,
    content: change.content,
    reason: change.reason
  }
}));
